const input = $json || {};

const region = input.region;
const userId = input.userId;
const connectionId = input.connectionId;
const externalId = input.externalId;
const platformAccountId = input.platformAccountId;
const awsAccountId = input.awsAccountId;
const roleName = input.roleName;
const stackName = input.stackName;
const connectionName = input.connectionName;
const templateUrl = input.templateUrl;
const provider = input.provider;
const setupMethod = input.setupMethod;

const queryParts = [
  'templateURL=' + encodeURIComponent(templateUrl),
  'stackName=' + encodeURIComponent(stackName),
  'param_PlatformAccountId=' + encodeURIComponent(platformAccountId),
  'param_ExternalId=' + encodeURIComponent(externalId),
  'param_IAMRoleName=' + encodeURIComponent(roleName)
];

const queryString = queryParts.join('&');
const cloudFormationLaunchUrl = `https://${region}.console.aws.amazon.com/cloudformation/home?region=${region}#/stacks/quickcreate?${queryString}`;

return {
  userId,
  connectionId,
  externalId,
  platformAccountId,
  awsAccountId,
  roleName,
  stackName,
  region,
  connectionName,
  cloudFormationLaunchUrl,
  provider,
  setupMethod,
  status: 'cloudformation_pending',
  roleStatus: 'unverified',
  createdAt: new Date().toISOString()
};
